import { createTool } from '../../lib/tool.js';
import { arrow, dot, label } from '../../lib/draw.js';
import { gcd, mod } from './_aa-math.js';

// Keep adding k on a clock with n hours. The points you visit form the subgroup generated by k.
const state = { n: 12, k: 1, t: 12 };

createTool({
  state,
  label: 'A clock with n marks. Starting at 0, arrows hop by k each time. Points that have been visited turn green. When k shares no factor with n the hops visit every mark before returning to 0.',
  draw(ctx, stage, c) {
    const [cx, cy, R] = [stage.w / 2, stage.h / 2, Math.min(stage.w, stage.h) * 0.38];
    const pos = (j) => [cx + R * Math.cos(-Math.PI / 2 + (2 * Math.PI * j) / state.n), cy + R * Math.sin(-Math.PI / 2 + (2 * Math.PI * j) / state.n)];
    const visited = new Set();
    for (let j = 0; j <= state.t; j++) visited.add(mod(j * state.k, state.n));
    const loop = state.n / gcd(state.k, state.n);
    for (let j = 0; j < Math.min(state.t, loop); j++) {
      const [x1, y1] = pos(mod(j * state.k, state.n));
      const [x2, y2] = pos(mod((j + 1) * state.k, state.n));
      const [dx, dy] = [x2 - x1, y2 - y1];
      const len = Math.hypot(dx, dy) || 1;
      arrow(ctx, x1 + (dx / len) * 12, y1 + (dy / len) * 12, x2 - (dx / len) * 13, y2 - (dy / len) * 13, { color: c.a, width: 2.5, head: 9 });
    }
    for (let j = 0; j < state.n; j++) {
      const [x, y] = pos(j);
      dot(ctx, x, y, state.n > 16 ? 10 : 13, j === 0 ? c.fillY : visited.has(j) ? c.fillC : c.paper, c.ink);
      label(ctx, String(j), x, y, c, { size: state.n > 16 ? 9 : 12, patch: false });
    }
    label(ctx, `${visited.size} of ${state.n} marks visited`, cx, cy, c, { size: 13 });
  },
  controls: [
    { title: 'Keep adding k' },
    { key: 'n', label: 'Marks on the clock, n', min: 2, max: 24, step: 1 },
    { key: 'k', label: 'Hop size, k', min: 1, max: 23, step: 1 },
    { key: 't', label: 'Hops made', min: 0, max: 24, step: 1 },
    { readout: [
      ['Hop size acts as', (s) => String(mod(s.k, s.n))],
      ['Returns home after', (s) => `${s.n / gcd(s.k, s.n)} hops`],
      ['Marks reached in all', (s) => String(s.n / gcd(s.k, s.n))],
      ['k builds everything?', (s) => ({ text: gcd(s.k, s.n) === 1 ? 'yes: k is a generator' : `no: only multiples of ${gcd(s.k, s.n)}`, good: gcd(s.k, s.n) === 1 })],
    ] },
  ],
  tex: (s) => `\\langle ${mod(s.k, s.n)}\\rangle=\\{0,${mod(s.k, s.n)},${mod(2 * s.k, s.n)},\\dots\\},\\ \\gcd(${s.k},${s.n})=${gcd(s.k, s.n)}`,
});
